package com.ejemplo.msa.service;
import com.ejemplo.msa.dto.EntityADto; import com.ejemplo.msa.client.DivisionUsageClient; import com.ejemplo.msa.entity.EntityA; import com.ejemplo.msa.repository.EntityARepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List; import java.util.Optional;
@Service public class EntityAService { private final EntityARepository repo; private final DivisionUsageClient usageClient; public EntityAService(EntityARepository repo,DivisionUsageClient usageClient){this.repo=repo;this.usageClient=usageClient;} private EntityADto dto(EntityA a){return new EntityADto(a.getId(),a.getNombreA());} public List<EntityADto> listar(){return repo.findAll().stream().map(this::dto).toList();} public Optional<EntityADto> buscar(Long id){return repo.findById(id).map(this::dto);} @Transactional public EntityADto crear(EntityADto d){if(repo.existsByNombreAIgnoreCase(d.getNombreA().trim()))throw new IllegalArgumentException("Ya existe una división con ese nombre"); EntityA a=new EntityA();a.setNombreA(d.getNombreA().trim());return dto(repo.save(a));} @Transactional public Optional<EntityADto> actualizar(Long id,EntityADto d){return repo.findById(id).map(a->{String n=d.getNombreA().trim();if(!a.getNombreA().equalsIgnoreCase(n)&&repo.existsByNombreAIgnoreCase(n))throw new IllegalArgumentException("Ya existe una división con ese nombre");a.setNombreA(n);return dto(repo.save(a));});} public boolean eliminar(Long id){if(!repo.existsById(id))return false;Boolean linked=usageClient.hasProgramsUsingDivision(id);if(Boolean.TRUE.equals(linked))throw new IllegalArgumentException("No se puede eliminar: la división tiene programas educativos asociados");repo.deleteById(id);return true;} @Transactional(readOnly=true) public List<EntityADto> findAllByIds(List<Long> ids){return repo.findAllById(ids).stream().map(this::dto).toList();} }
